1	import { spawnSync } from 'node:child_process';
2	import { readFileSync, existsSync, statSync } from 'node:fs';
3	import { join, resolve, sep } from 'node:path';
4	import { parseEntries } from './session-transcript.mjs';
5	import { SHARED_SUBDIR, packEntryId } from '../../pack_loader/pack-registry.mjs';
6	
7	function sh(root, cmd, args, { allowFail = false, input = undefined, timeout = undefined } = {}) {
8	  const r = spawnSync(cmd, args, { cwd: root, encoding: 'utf8', maxBuffer: 64 * 1024 * 1024, input, timeout });
9	  if (r.status !== 0 && !allowFail) {
10	    throw new Error(`${cmd} ${args.join(' ')} failed (${r.status}): ${r.stderr}`);
11	  }
12	  return r.status === 0 ? r.stdout : null;
13	}
14	
15	const git = (root, ...args) => sh(root, 'git', args);
16	const gitTry = (root, ...args) => sh(root, 'git', args, { allowFail: true });
17	
18	function resolveBaseRef(root) {
19	  for (const ref of ['origin/main', 'origin/master', 'main', 'master']) {
20	    if (gitTry(root, 'rev-parse', '--verify', '--quiet', `${ref}^{commit}`) !== null) return ref;
21	  }
22	  return null;
23	}
24	
25	const FETCH_TIMEOUT_MS = 8000;
26	
27	// A remote-tracking base ref is only as fresh as the last fetch, and a cloud session's
28	// clone freezes it at container-creation time — so every commit the base branch gained
29	// since lands inside `mergeBase..HEAD` and gets billed to the work. That is a wrong
30	// verdict, not a stale one: the delta rules (squash-merge-history above all, a *blocking*
31	// rule) report other people's commits as introduced by this change, and `--changed`
32	// widens to files the change never touched. Refreshing the ref once per run is what makes
33	// "the work" mean the work.
34	//
35	// Best-effort by construction — no network, no remote, a lock held, a slow server: the
36	// fetch fails or times out and the run continues against the ref as it stands, exactly as
37	// before this existed. It writes ONLY the remote-tracking ref (explicit refspec, no tags):
38	// no local branch, no index, no working tree, nothing the session could be surprised by.
39	// Set CLAUDINITE_CHECKS_NO_FETCH=1 to skip it (sealed sandboxes, or to pin a base).
40	function refreshBaseRef(root, ref) {
41	  if (!ref || process.env.CLAUDINITE_CHECKS_NO_FETCH === '1') return;
42	  const m = /^([^/]+)\/(.+)$/.exec(ref);
43	  if (!m) return; // a local branch is already as current as the checkout — nothing to fetch
44	  const [, remote, branch] = m;
45	  sh(root, 'git', ['fetch', '--quiet', '--no-tags', remote,
46	    `+refs/heads/${branch}:refs/remotes/${remote}/${branch}`],
47	  { allowFail: true, timeout: FETCH_TIMEOUT_MS });
48	}
49	
50	function lines(out) {
51	  return (out || '').split('\n').filter(Boolean);
52	}
53	
54	// Files git marks vendored or generated (linguist-vendored / linguist-generated in
55	// .gitattributes) — third-party or machine-written content, not the project's own
56	// code. `buildContext` drops these from the default `ctx.files`, so every check that
57	// reasons about "the project's code" skips them for free: a suppression marker inside
58	// a recorded fixture, a placement "violation" in a generated artifact, and a dangling
59	// link in a vendored doc are none of them the project's decision. `git check-attr`
60	// honors .gitattributes patterns/precedence natively (paths on stdin so a large repo
61	// can't overflow the arg list). The unfiltered set stays on `ctx.allFiles` for the one
62	// check that reasons *about* generated files (generated-merge-driver).
63	function vendoredSet(root, files) {
64	  const set = new Set();
65	  if (!files.length) return set;
66	  const out = sh(root, 'git', ['check-attr', '--stdin', 'linguist-vendored', 'linguist-generated'],
67	    { allowFail: true, input: files.join('\n') + '\n' });
68	  for (const line of (out || '').split('\n')) {
69	    const m = /^(.*): (?:linguist-vendored|linguist-generated): (.*)$/.exec(line);
70	    if (m && m[2] === 'set') set.add(m[1]);
71	  }
72	  return set;
73	}
74	
75	// The complete set of top-level settings .claudinite-checks.json may carry. A key
76	// outside this set is a typo or a stale name — a settings error as real as invalid
77	// JSON, caught at load so it can't silently change nothing. `packConfig` is the
78	// legacy home of per-pack parameters — still honored while the fleet migrates to
79	// pack-entry `config` (the baselining folds it in), no longer documented. The
80	// `pack-entry-config` baseline migration (migrations/active_migrations/) tracks
81	// the fleet's convergence; when it retires, drop the key here (and the overlay
82	// below) so a straggler gets the unknown-setting error.
83	// `claudinite` is the vendored-mount stamp — { updated: "<ISO datetime>", ref: "<sha>" },
84	// written by the nightly update pass, selecting which migration notes still apply
85	// (vendoring/DESIGN.md owns the model); the checks engine itself only tolerates it.
86	// `taskScheduler` is the per-repo maintenance anchor the vendored hourly scheduler
87	// reads (per-project-scheduling DESIGN §2) — { dailyHour, weeklyDay, monthlyDay },
88	// all UTC. Absence means the documented defaults, so an omitted key is not an
89	// error; a present one is range-validated at load below. Its declaration is also
90	// the per-repo cutover marker during the scheduling rollout (MIGRATION Phase 0.6).
91	// `badges` is the repo's say over the pack-badge row baselining maintains in its
92	// README — { readme: 'auto' | 'off' }. Materialized explicitly into every member
93	// (the wiring converge writes it) rather than inferred from absence, so the knob
94	// sits visibly in the file anyone would open to change it.
95	// `dormant` is the project's own declaration that it is out of the RECURRING work —
96	// see isDormant below for exactly how much that covers.
97	export const CONFIG_KEYS = ['packs', 'rules', 'accept', 'sharedConstants', 'packConfig', 'maintenance', 'claudinite', 'taskScheduler', 'badges', 'dormant'];
98	
99	// Does this project declare itself DORMANT? A project goes dormant when it is
100	// finished, parked, or simply not being worked on: it should stop paying the
101	// upkeep of a project that IS being worked on.
102	//
103	// What dormancy means, exactly — it is narrow on purpose:
104	//   - NO RECURRING WORK. The vendored scheduler stops before it evaluates
105	//     anything (engine/scheduler/run.mjs), so no task is due, no dispatch issue
106	//     is filed, no agent session is started, and no maintenance PR is opened.
107	//     Nothing scheduled runs "for nothing" on a repo nobody is working on.
108	//   - NO FLEET CEREMONY. Whatever looks at this repo from the OUTSIDE reads the
109	//     same declaration and leaves it alone rather than reporting it as unhealthy —
110	//     a repo TOLD to stop keeping up must not then be nagged for not keeping up.
111	//     Which is why this predicate is exported for a raw declaration too (below).
112	//   - EVERYTHING ELSE STAYS ON. Claudinite is not switched off: the session
113	//     hooks, the checks engine, the mounted skills and pack prose all work
114	//     exactly as before the moment someone opens a session on the repo. Dormancy
115	//     is about unattended upkeep, never about what an interactive session may do.
116	//
117	// The predicate reads BOTH shapes deliberately: a raw parsed .claudinite-checks.json
118	// and the normalized config loadConfig returns. A cross-repo reader fetches another
119	// repo's declaration over the API with no engine loaded against that tree, and it
120	// must decide dormancy by the same test that repo's own scheduler used — a second
121	// notion of dormancy would nag exactly the repos that had already opted out. One
122	// definition, both sides.
123	export const isDormant = (config) => config?.dormant === true;
124	
125	// The keys a `schedule` object may carry, and the canonical weekday vocabulary
126	// (mirrored from engine/scheduler/slots.mjs WEEKDAYS — kept as a literal here so
127	// the checks layer does not import the scheduler engine).
128	const SCHEDULE_KEYS = ['dailyHour', 'weeklyDay', 'monthlyDay'];
129	const SCHEDULE_WEEKDAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
130	
131	// The properties a `packs` entry object may carry: the pack's parameters
132	// (`config`), its adoption-interview answers (`answers` — the owner's verbatim
133	// responses to the questions the pack declares on its pack.mjs, keyed by
134	// question id; read by the adoption skill's interview machinery), and the rule overrides / acceptances that
135	// exist BECAUSE this pack is declared (`rules`, `accept` — they may name any
136	// rule; the entry is their provenance). `via` is written by
137	// resolveDeclaredPacks on materialized dependencies (engine/pack_loader/pack-registry.mjs).
138	export const PACK_ENTRY_KEYS = ['id', 'config', 'answers', 'rules', 'accept', 'via'];
139	
140	// Load and validate the project's settings. Validity is checked at load — the
141	// moment Claudinite reads the file — and every problem is collected into `errors`
142	// (each `{ what, fix }`), the runner's single settings-validity gate. A wrong
143	// property name, malformed JSON, and a wrong pack name are all equally settings
144	// errors; unknown *pack* names need the registry, so the runner adds those (it
145	// holds the known-pack list). On unparsable/misshaped JSON the usable fields fall
146	// back to empty so the rest of a sweep still runs, with the error reported.
147	//
148	// The returned shape is NORMALIZED: `packs` is plain BARE ids (a local pack's
149	// namespaced `local_packs/<id>` token resolves through packEntryId, so every
150	// downstream lookup — packEntries, the packConfig view — keys by the pack's
151	// own id whichever form the file used), `rules` and `accept` are the top-level
152	// and per-entry settings merged (an entry-sourced acceptance carries
153	// `pack: <id>` as provenance; conflicting severity overrides are a settings
154	// error), and `packConfig` is the per-pack parameter view — each entry's
155	// `config`, overlaid on the legacy top-level key. Checks and env machinery
156	// read this one shape regardless of which form the file used.
157	export function loadConfig(root) {
158	  const path = join(root, '.claudinite-checks.json');
159	  const empty = { packs: [], packEntries: [], rules: {}, accept: [], sharedConstants: [], packConfig: {}, taskScheduler: null, claudinite: null, maintenance: null, badges: null, dormant: false, errors: [] };
160	  if (!existsSync(path)) return empty;
161	
162	  let raw;
163	  try {
164	    raw = JSON.parse(readFileSync(path, 'utf8'));
165	  } catch (e) {
166	    return { ...empty, errors: [{ what: `.claudinite-checks.json is not valid JSON: ${e.message}`, fix: 'fix the JSON syntax' }] };
167	  }
168	  if (raw === null || typeof raw !== 'object' || Array.isArray(raw)) {
169	    return { ...empty, errors: [{ what: '.claudinite-checks.json must be a JSON object', fix: 'wrap the settings in an object: { "packs": [ ... ] }' }] };
170	  }
171	
172	  const errors = [];
173	  for (const key of Object.keys(raw)) {
174	    if (!CONFIG_KEYS.includes(key)) {
175	      errors.push({ what: `unknown setting "${key}"`, fix: `remove it or fix the name — valid settings: ${CONFIG_KEYS.join(', ')}` });
176	    }
177	  }
178	
179	  // --- packs: each entry a pack id or { id, config?, rules?, accept?, via? } ---
180	  const packs = [];
181	  const packEntries = [];
182	  for (const entry of Array.isArray(raw.packs) ? raw.packs : []) {
183	    if (typeof entry === 'string') {
184	      packs.push(packEntryId(entry));
185	      packEntries.push({ id: packEntryId(entry) });
186	      continue;
187	    }
188	    if (entry === null || typeof entry !== 'object' || Array.isArray(entry)) {
189	      errors.push({ what: `packs entry ${JSON.stringify(entry)} is neither a pack id nor an entry object`, fix: 'declare a pack as "name" or { "id": "name", ... }' });
190	      continue;
191	    }
192	    if (typeof entry.id !== 'string') {
193	      errors.push({ what: `packs entry ${JSON.stringify(entry)} has no "id"`, fix: 'give the entry an "id": the pack name' });
194	      continue;
195	    }
196	    for (const key of Object.keys(entry)) {
197	      if (!PACK_ENTRY_KEYS.includes(key)) {
198	        errors.push({ what: `unknown property "${key}" on the "${entry.id}" pack entry`, fix: `remove it or fix the name — valid entry properties: ${PACK_ENTRY_KEYS.join(', ')}` });
199	      }
200	    }
201	    const badShape = (prop, expected) =>
202	      errors.push({ what: `"${prop}" on the "${entry.id}" pack entry must be ${expected}`, fix: `fix or remove the entry's "${prop}"` });
203	    const normalized = { id: packEntryId(entry) };
204	    if (entry.config !== undefined) {
205	      if (entry.config !== null && typeof entry.config === 'object' && !Array.isArray(entry.config)) normalized.config = entry.config;
206	      else badShape('config', 'an object of the pack\'s parameters');
207	    }
208	    if (entry.answers !== undefined) {
209	      if (entry.answers !== null && typeof entry.answers === 'object' && !Array.isArray(entry.answers)
210	        && Object.values(entry.answers).every((v) => typeof v === 'string')) normalized.answers = entry.answers;
211	      else badShape('answers', 'an object mapping the pack\'s question ids to string answers');
212	    }
213	    if (entry.rules !== undefined) {
214	      if (entry.rules !== null && typeof entry.rules === 'object' && !Array.isArray(entry.rules)) normalized.rules = entry.rules;
215	      else badShape('rules', 'an object of per-rule severity overrides');
216	    }
217	    if (entry.accept !== undefined) {
218	      if (Array.isArray(entry.accept)) normalized.accept = entry.accept;
219	      else badShape('accept', 'an array of acceptance entries');
220	    }
221	    if (entry.via !== undefined) {
222	      // Written by the declaration resolver on materialized dependencies
223	      // (engine/pack_loader/pack-registry.mjs) — normalized through so readers (the adoption
224	      // interview) can tell a chosen pack from a pulled-in one.
225	      if (Array.isArray(entry.via) && entry.via.every((v) => typeof v === 'string')) normalized.via = entry.via;
226	      else badShape('via', 'an array of pack ids (the declaration resolver writes it)');
227	    }
228	    packs.push(normalized.id);
229	    packEntries.push(normalized);
230	  }
231	
232	  // --- rules: top-level and per-entry merged; a conflict is a settings error,
233	  // never a silent last-writer-wins — two packs (or a pack and the top level)
234	  // disagreeing about a rule's severity is a decision the project must make.
235	  const rules = {};
236	  const ruleSource = {};
237	  const mergeRules = (overrides, source) => {
238	    for (const [ruleId, severity] of Object.entries(overrides)) {
239	      if (ruleId in rules && rules[ruleId] !== severity) {
240	        errors.push({
241	          what: `rule "${ruleId}" is set to "${rules[ruleId]}" by ${ruleSource[ruleId]} and "${severity}" by ${source}`,
242	          fix: 'make the overrides agree, or keep the rule on one of them',
243	        });
244	        continue;
245	      }
246	      rules[ruleId] = severity;
247	      ruleSource[ruleId] = source;
248	    }
249	  };
250	  if (raw.rules && typeof raw.rules === 'object') mergeRules(raw.rules, 'the top-level "rules"');
251	  for (const entry of packEntries) {
252	    if (entry.rules) mergeRules(entry.rules, `the "${entry.id}" pack entry`);
253	  }
254	
255	  // --- accept: top-level entries, then each pack entry's stamped with its
256	  // provenance (`pack: <id>` — which declaration motivated the exemption).
257	  const accept = Array.isArray(raw.accept) ? [...raw.accept] : [];
258	  for (const entry of packEntries) {
259	    for (const a of entry.accept ?? []) accept.push({ ...a, pack: entry.id });
260	  }
261	
262	  // --- packConfig view: per-pack parameters — e.g. the dirs a repo's
263	  // package.json lives in for the node pack's env install. Entry `config` is
264	  // the home; the legacy top-level key stays readable underneath it.
265	  const packConfig = raw.packConfig && typeof raw.packConfig === 'object' && !Array.isArray(raw.packConfig) ? { ...raw.packConfig } : {};
266	  for (const entry of packEntries) {
267	    if (entry.config !== undefined) packConfig[entry.id] = entry.config;
268	  }
269	
270	  // --- taskScheduler: the per-repo maintenance anchor (UTC). Range-validated at
271	  // load so a bad anchor is a settings error like any other; absence is legal
272	  // (the scheduler fills the documented defaults). The value passes through
273	  // unchanged for the scheduler to normalize.
274	  let taskScheduler = null;
275	  if (raw.taskScheduler !== undefined) {
276	    if (raw.taskScheduler === null || typeof raw.taskScheduler !== 'object' || Array.isArray(raw.taskScheduler)) {
277	      errors.push({ what: '"taskScheduler" must be an object', fix: 'e.g. { "dailyHour": 4, "weeklyDay": "Sun", "monthlyDay": 1 }' });
278	    } else {
279	      for (const key of Object.keys(raw.taskScheduler)) {
280	        if (!SCHEDULE_KEYS.includes(key)) {
281	          errors.push({ what: `unknown "taskScheduler" setting "${key}"`, fix: `remove it or fix the name — valid taskScheduler settings: ${SCHEDULE_KEYS.join(', ')}` });
282	        }
283	      }
284	      const { dailyHour, weeklyDay, monthlyDay } = raw.taskScheduler;
285	      if (dailyHour !== undefined && !(Number.isInteger(dailyHour) && dailyHour >= 0 && dailyHour <= 23)) {
286	        errors.push({ what: `"taskScheduler.dailyHour" must be an integer 0–23 (UTC), got ${JSON.stringify(dailyHour)}`, fix: 'set an hour of the day, 0 through 23' });
287	      }
288	      if (weeklyDay !== undefined && !SCHEDULE_WEEKDAYS.includes(weeklyDay)) {
289	        errors.push({ what: `"taskScheduler.weeklyDay" must be one of ${SCHEDULE_WEEKDAYS.join(', ')}, got ${JSON.stringify(weeklyDay)}`, fix: 'name a weekday, e.g. "Sun"' });
290	      }
291	      if (monthlyDay !== undefined && !(Number.isInteger(monthlyDay) && monthlyDay >= 1 && monthlyDay <= 31)) {
292	        errors.push({ what: `"taskScheduler.monthlyDay" must be an integer 1–31, got ${JSON.stringify(monthlyDay)}`, fix: 'set a day of the month, 1 through 31 (clamped to the month length)' });
293	      }
294	      taskScheduler = raw.taskScheduler;
295	    }
296	  }
297	
298	  // --- dormant: a plain boolean, validated as one. A string "true", a `{ since }`
299	  // object or a reason left in its place would all read as dormant to a truthiness
300	  // test and as active to this one, and the difference is a whole repo's scheduled
301	  // work — so the wrong TYPE is a settings error, not a value to coerce.
302	  if (raw.dormant !== undefined && typeof raw.dormant !== 'boolean') {
303	    errors.push({
304	      what: `"dormant" must be true or false, got ${JSON.stringify(raw.dormant)}`,
305	      fix: 'set "dormant": true to stop this project\'s recurring work, or remove the key',
306	    });
307	  }
308	
309	  return {
310	    packs,
311	    packEntries,
312	    rules,
313	    accept,
314	    sharedConstants: Array.isArray(raw.sharedConstants) ? raw.sharedConstants : [],
315	    packConfig,
316	    taskScheduler,
317	    // Passed through as declared, not normalized: `claudinite` is the
